-- Wissensseiten: Zusatzabschnitte nach Suchbegriffen (GSC 09.11.2026), Freigabe P. Schenkelberger 09.11.2026
-- Im Supabase-SQL-Editor ausführen. Fügt daten.abschnitte hinzu bzw. ersetzt es; übrige Felder bleiben.
begin;
update lerninhalte set daten = daten || jsonb_build_object('abschnitte', '[{"titel": "CRP-Wert Tabelle: mg/l und mg/dl", "text": "Labore geben das CRP in mg/l oder in mg/dl an. Umrechnung: 1 mg/dl = 10 mg/l.", "tabelle": {"kopf": ["CRP in mg/l", "CRP in mg/dl", "Einordnung (Orientierung)"], "zeilen": [["unter 5", "unter 0,5", "normal (manche Labore: unter 10 mg/l)"], ["5–50", "0,5–5", "leichte Entzündung, oft viral oder lokal"], ["50–100", "5–10", "deutliche Entzündung"], ["über 100", "über 10", "starker Hinweis auf bakterielle Infektion"], ["über 200", "über 20", "schwere bakterielle Infektion, an Sepsis denken"]]}, "nach": "Die Grenzen sind Lehrbuch-Orientierung, keine festen Normgrenzen. Maßgeblich ist der Referenzbereich des eigenen Labors."}, {"titel": "Wie hoch darf ein Entzündungswert sein?", "text": "Beim Erwachsenen liegt das CRP normal unter 5 mg/l (0,5 mg/dl), die Leukozyten bei 4.000–10.000/µl und das PCT unter 0,05 ng/ml. Leicht erhöhte Werte kommen auch bei Rauchern, Übergewicht, nach Sport oder nach Operationen vor. Entscheidend ist der Verlauf zusammen mit Fieber, Puls, Atemfrequenz und Allgemeinzustand."}, {"titel": "Warum steigt das CRP nach einer Operation?", "text": "Jede Operation ist ein Gewebeschaden. Das CRP steigt deshalb auch ohne Infektion an, mit einem Gipfel am 2. bis 3. Tag, und fällt danach wieder. Steigt es nach dem 3. bis 4. Tag erneut an, ist das ein Warnzeichen, etwa für eine Wundinfektion, Pneumonie oder Anastomoseninsuffizienz."}, {"titel": "Viral oder bakteriell?", "text": "Bei Virusinfekten bleibt das CRP meist unter 50 mg/l und das PCT niedrig. Bei bakteriellen Infektionen steigen CRP und PCT oft deutlich. Eine sichere Unterscheidung erlauben die Werte allein nicht."}]'::jsonb), stand = current_date, geprueft_von = 'P. Schenkelberger', geprueft_am = current_date where slug = 'entzuendungswerte';
update lerninhalte set daten = daten || jsonb_build_object('abschnitte', '[{"titel": "COPD: FEV1-Werte und GOLD-Stadien", "text": "Voraussetzung für die Einteilung ist eine Obstruktion: Tiffeneau-Index (FEV1/FVC) unter 0,7 nach Gabe eines Bronchodilatators.", "tabelle": {"kopf": ["GOLD-Stadium", "FEV1 in % vom Sollwert", "Schweregrad"], "zeilen": [["GOLD 1", "80 % und mehr", "leicht"], ["GOLD 2", "50–79 %", "mittelgradig"], ["GOLD 3", "30–49 %", "schwer"], ["GOLD 4", "unter 30 %", "sehr schwer"]]}, "nach": "Für die Therapie wird zusätzlich nach Beschwerden und Exazerbationen eingeteilt (Gruppen A, B, E)."}, {"titel": "Tiffeneau-Index bei COPD", "text": "Der Tiffeneau-Index ist der Anteil der FEV1 an der Vitalkapazität. Gesunde atmen etwa 75–85 % in der ersten Sekunde aus. Liegt der Wert unter 70 % (0,7), besteht eine Obstruktion."}, {"titel": "Bronchospasmolysetest: Asthma oder COPD?", "text": "Die FEV1 wird vor und etwa 15 Minuten nach einem kurz wirksamen Bronchodilatator (z. B. Salbutamol) gemessen. Eine Zunahme um mindestens 12 % und mindestens 200 ml gilt als deutliche Reversibilität und spricht eher für Asthma. Bei COPD bleibt die Obstruktion weitgehend bestehen."}, {"titel": "BGA-Werte bei COPD", "tabelle": {"kopf": ["Situation", "pO₂", "pCO₂", "pH", "HCO₃⁻"], "zeilen": [["leichte, stabile COPD", "oft normal", "normal", "normal", "normal"], ["fortgeschritten, chronisch", "erniedrigt (unter 60 mmHg)", "erhöht (über 45 mmHg)", "normal (kompensiert)", "erhöht"], ["akute Exazerbation", "erniedrigt", "steigt weiter an", "unter 7,35 (respiratorische Azidose)", "erhöht"]]}, "nach": "Ziel-Sättigung bei Hyperkapnie-Risiko: SpO₂ 88–92 %. Eine akute respiratorische Azidose ist ein Warnzeichen; oft wird dann eine NIV erwogen."}, {"titel": "Welcher Pflegegrad bei COPD GOLD 3 oder 4?", "text": "Der Pflegegrad hängt nicht vom GOLD-Stadium ab. Er richtet sich nach der Selbstständigkeit im Alltag, die der Medizinische Dienst in sechs Lebensbereichen begutachtet (z. B. Mobilität, Selbstversorgung, Umgang mit therapiebedingten Anforderungen wie Sauerstoff oder Inhalation). Menschen mit GOLD 3 oder 4 brauchen oft Hilfe, der Pflegegrad wird aber immer einzeln festgestellt."}]'::jsonb), stand = current_date, geprueft_von = 'P. Schenkelberger', geprueft_am = current_date where slug = 'lungenfunktion';
update lerninhalte set daten = daten || jsonb_build_object('abschnitte', '[{"titel": "Lagerungen im Überblick: 30, 45, 90 und 135 Grad", "tabelle": {"kopf": ["Lagerung", "Wofür", "So geht’s", "Achtung"], "zeilen": [["30-Grad-Seitenlage (Schräglage)", "Dekubitusprophylaxe", "Körper mit Kissen unter Rücken und Gesäß ca. 30 Grad zur Seite gedreht, Seiten im Wechsel", "Kreuzbein und Trochanter liegen frei, Fersen freilagern"], ["Oberkörperhochlage 30–45 Grad", "Aspirations- und Pneumonieprophylaxe, Atmung, Sondenernährung, Beatmung", "Kopfteil 30–45 Grad hoch, Knie leicht unterstützt gegen Rutschen", "Scherkräfte am Gesäß, Kreuzbein kontrollieren"], ["90-Grad-Seitenlage", "Atemtherapie, Belüftung der oben liegenden Lunge, Pflegemaßnahmen", "Volle Seitenlage, Rücken mit Kissen gestützt, unteres Bein gestreckt, oberes angewinkelt", "Hoher Druck auf den Trochanter, nicht zur Dekubitusprophylaxe, nur kurz"], ["135-Grad-Lagerung", "Entlastung des ganzen Rückens, Belüftung der hinteren Lungenabschnitte", "Halbe Bauchlage, Kissen unter Brust und Becken der oberen Seite, Arm vor dem Körper", "Nur mit ärztlicher Freigabe bei Wirbelsäulen-OP oder instabilem Kreislauf"], ["Bauchlage", "ARDS auf der Intensivstation (Oxygenierung)", "Nur im Team nach Standard, meist 16 Stunden und länger", "Gesicht, Augen, Brust, Knie, Tubus und Zugänge sichern"], ["Herzbettlagerung", "Herzinsuffizienz, Lungenödem (senkt die Vorlast)", "Oberkörper hoch, Beine tief", "Nicht bei niedrigem Blutdruck oder Schock"], ["V-, A-, T-, I-Lagerung", "Belüftung einzelner Lungenabschnitte", "Kissen in V-, A-, T- oder I-Form unter den Rücken", "Nur kurz (z. B. 10–20 Minuten), Atmung beobachten"]]}, "nach": "Zeitangaben sind Orientierung; es gilt der Standard der Einrichtung."}, {"titel": "30-Grad-Lagerung: links oder rechts?", "text": "Beide Seiten werden im Wechsel genutzt, damit nicht immer dieselben Stellen belastet werden. Ausnahmen klärt das Team, etwa bei Halbseitenlähmung, frischer Hüft-OP oder Wunden."}, {"titel": "Lagern oder Positionieren?", "text": "In neueren Lehrbüchern und im Expertenstandard Dekubitusprophylaxe heißt es eher „Positionierung“ und „Bewegungsförderung“. Gemeint ist dasselbe, betont wird aber die Eigenbewegung des Menschen."}, {"titel": "Wie oft umlagern?", "text": "Ein festes Intervall wie „alle 2 Stunden“ gibt es nicht mehr. Die Häufigkeit richtet sich nach Risiko, Hautbefund und Unterlage und wird im Bewegungsplan festgelegt und überprüft."}]'::jsonb), stand = current_date, geprueft_von = 'P. Schenkelberger', geprueft_am = current_date where slug = 'lagerungsarten';
update lerninhalte set daten = daten || jsonb_build_object('abschnitte', '[{"titel": "BIPAP-Beatmung einfach erklärt", "text": "Bei BIPAP wechselt das Gerät zwischen zwei Druckniveaus: einem oberen Druck (P insp, P hoch) und einem unteren Druck (PEEP). Der Wechsel erfolgt mit der eingestellten Frequenz und Inspirationszeit. Der Patient darf auf beiden Niveaus jederzeit selbst atmen. Atmet er gar nicht, wirkt BIPAP wie eine druckkontrollierte Beatmung. Oft wird zusätzlich eine Druckunterstützung (ASB) für die eigenen Atemzüge eingestellt (BIPAP/ASB).\nNicht verwechseln: „BiPAP“ ist auch ein Markenname für NIV-Geräte mit Maske. Gemeint ist dort ebenfalls Beatmung mit zwei Druckniveaus; die Bezeichnungen unterscheiden sich je nach Hersteller."}, {"titel": "Druckkontrolliert (PCV) oder volumenkontrolliert (VCV)?", "tabelle": {"kopf": ["", "PCV (druckkontrolliert)", "VCV (volumenkontrolliert)"], "zeilen": [["Eingestellt", "Druck, Frequenz, Inspirationszeit", "Atemzugvolumen, Frequenz"], ["Ergibt sich", "Atemzugvolumen", "Beatmungsdruck"], ["Vorteil", "Druck ist begrenzt, lungenschonend", "Volumen und Minutenvolumen sind sicher"], ["Nachteil", "Volumen sinkt bei Sekret, Bronchospasmus oder steifer Lunge", "Druck kann gefährlich ansteigen"], ["Darauf achten", "Atemzugvolumen und Minutenvolumen", "Spitzendruck und Plateaudruck"]]}, "nach": "APCV ist eine druckkontrollierte Beatmung, bei der der Patient zusätzliche Atemzüge auslösen kann, die das Gerät dann voll übernimmt."}, {"titel": "Beatmungsparameter: Abkürzungen", "tabelle": {"kopf": ["Abkürzung", "Bedeutung", "Richtwert Erwachsene"], "zeilen": [["Vt / AZV", "Atemzugvolumen", "6–8 ml/kg ideales Körpergewicht"], ["AF / f", "Atemfrequenz", "12–20/min"], ["AMV / MV", "Atemminutenvolumen = Vt × AF", "ca. 6–8 l/min"], ["PEEP", "positiver Druck am Ende der Ausatmung", "meist 5–10 cmH₂O"], ["P insp", "eingestellter Inspirationsdruck", "nach Anordnung"], ["P peak / P max", "Spitzendruck", "Alarmgrenze nach Anordnung"], ["P plat", "Plateaudruck", "möglichst ≤ 30 cmH₂O"], ["FiO₂", "Sauerstoffanteil der Einatemluft", "0,21–1,0, so niedrig wie möglich"], ["I:E", "Verhältnis Ein- zu Ausatemzeit", "meist 1:2"], ["ASB / PS", "Druckunterstützung eigener Atemzüge", "nach Anordnung"], ["CMV / IPPV", "vollständig kontrollierte Beatmung", "–"], ["SIMV", "Pflichtatemzüge plus Spontanatmung", "–"], ["CPAP", "Spontanatmung mit dauerhaft positivem Druck", "–"], ["NIV", "Beatmung über Maske ohne Tubus", "–"]]}, "nach": "Beispiel Minutenvolumen: 500 ml × 14/min = 7 l/min."}]'::jsonb), stand = current_date, geprueft_von = 'P. Schenkelberger', geprueft_am = current_date where slug = 'beatmungsmodi';
-- Pflegeplanung COPD: Begründung der O2-Grenze (V/Q-Verhältnis, Haldane-Effekt statt nur hypoxischer Atemantrieb)
update lerninhalte set daten = jsonb_set(daten, '{mcq,0}', '{"frage": "Warum darf COPD-Patienten NICHT unkontrolliert hochdosiert O₂ gegeben werden?", "richtig": 1, "optionen": ["O₂ ist zu teuer", "Zu viel O₂ kann das pCO₂ ansteigen lassen (Gefahr der CO₂-Narkose)", "O₂ verschlimmert Bronchitis", "Keine Kontraindikation"]}'::jsonb), stand = current_date where slug = 'pflegeplanung-copd' and daten->'mcq'->0->>'frage' like 'Warum darf COPD%';
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung,0,massnahmen,0}', to_jsonb('O₂-Gabe VORSICHTIG: Ziel SpO₂ 88–92 % (nicht höher! Gefahr des CO₂-Anstiegs)'::text)) where slug = 'pflegeplanung-copd' and daten->'pflegeplanung'->0->'massnahmen'->>0 like 'O₂-Gabe VORSICHTIG%';
commit;
-- Kontrolle: select slug, jsonb_array_length(daten->'abschnitte') from lerninhalte where slug in ('entzuendungswerte','lungenfunktion','lagerungsarten','beatmungsmodi');
